import sys

def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n-1)

# Read input
tokens = sys.stdin.read().split()
n = int(tokens[0])

# Calculate and print factorial for each value of n
for i in range(n+1):
    print(factorial(i))

